//! Verifies the metadata generated by the public derive macro.

use std::any::{TypeId, type_name};

use mythraan_reflect::prelude::{Reflect, TypeInfo, TypeRegistry};

#[derive(Reflect)]
struct Settings<T> {
    #[reflect(range = -1.0..=1.0)]
    intensity: f64,
    #[reflect(hidden, range = 0..10)]
    r#type: u8,
    payload: T,
}

#[derive(Reflect)]
enum Mode {
    Linear,
    Loop,
}

#[test]
fn derives_fields_and_preserves_attributes() {
    let Settings {
        intensity,
        r#type,
        payload,
    } = Settings {
        intensity: 0.0,
        r#type: 7,
        payload: false,
    };
    assert_eq!((intensity, r#type, payload), (0.0, 7, false));

    let [intensity, hidden, payload] = TypeInfo::of::<Settings<bool>>().fields() else {
        panic!("expected three fields");
    };
    assert_eq!(
        (intensity.name(), intensity.type_id()),
        ("intensity", TypeId::of::<f64>())
    );
    let range = intensity.range().unwrap();
    assert_eq!(
        (range.min(), range.max(), range.is_inclusive()),
        (-1.0, 1.0, true)
    );
    assert!(!intensity.is_hidden());
    assert_eq!(
        (hidden.name(), hidden.type_id()),
        ("type", TypeId::of::<u8>())
    );
    assert!(hidden.is_hidden());
    let range = hidden.range().unwrap();
    assert_eq!(
        (range.min(), range.max(), range.is_inclusive()),
        (0.0, 10.0, false)
    );
    assert_eq!(payload.type_id(), TypeId::of::<bool>());
    assert_eq!(payload.range(), None);
}

#[test]
fn registers_derived_enum_metadata() {
    let _modes = [Mode::Linear, Mode::Loop];
    let mut registry = TypeRegistry::new();
    registry.register::<Mode>().unwrap();
    let info = registry.get_by_name(type_name::<Mode>()).unwrap();
    assert_eq!(registry.get_by_id(TypeId::of::<Mode>()), Some(info));
    assert_eq!(info.variants(), ["Linear", "Loop"]);
    assert!(info.fields().is_empty());
}
